public class SumaParesImpares {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Introduce un número N: ");
        int n = scanner.nextInt();

        int sumaPares = 0;
        int sumaImpares = 0;

