import java.util.Deque;

public class EjemploInsertionDeque {
    public static void main(String[] args) {
        Deque&lt;String&gt; baraja = new ArrayDeque&lt;&gt;();

        // Inserción al PRINCIPIO (Arriba del mazo)
        baraja.addFirst("As de Corazones"); // void / Excepción si falla
        boolean ok1 = baraja.offerFirst("Rey de Picas"); // boolean

        // Inserción al FINAL (Abajo del mazo)
        baraja.addLast("2 de Tréboles"); // void / Excepción si falla
        boolean ok2 = baraja.offerLast("Joker"); // boolean

        System.out.println(baraja);
        // Orden: [Rey de Picas, As de Corazones, 2 de Tréboles, Joker]
    }
}
