import java.util.Deque;

public class EjemploRemovalDeque {
    public static void main(String[] args) {
        Deque&lt;String&gt; baraja = new ArrayDeque&lt;&gt;();
        baraja.add("Carta 1");
        baraja.add("Carta 2");

        // Sacar de ARRIBA (First)
        String c1 = baraja.removeFirst(); // Lanza Excepción si vacía
        String c2 = baraja.pollFirst();   // Devuelve null si vacía

        // Sacar de ABAJO (Last) - Intentamos sacar de lista vacía
        // String error = baraja.removeLast(); // ¡CRASH! NoSuchElementException
        String seguro = baraja.pollLast();    // null, todo bien.

        System.out.println("Seguro: " + seguro);
    }
}
