import java.util.Deque;

public class EjemploInspectionDeque {
    public static void main(String[] args) {
        Deque&lt;String&gt; historial = new ArrayDeque&lt;&gt;();
        historial.add("Google.com");
        historial.add("Youtube.com");

        // Mirar el primero (First - Google)
        System.out.println("First (Dramático): " + historial.getFirst());
        System.out.println("First (Seguro): " + historial.peekFirst());

        // Mirar el último (Last - Youtube)
        System.out.println("Last (Dramático): " + historial.getLast());
        System.out.println("Last (Seguro): " + historial.peekLast());

        // No modifican la lista, solo miran.
        System.out.println("Tamaño sigue siendo: " + historial.size());
    }
}
