Solución <pre><code>import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Scanner;
import java.util.stream.Stream;

public class GestionFicherosNio {

    private static final Path BASE = Path.of("datos");

    public static void main(String[] args) {
        try {
            Files.createDirectories(BASE);
        } catch (IOException e) {
            System.err.println("No se pudo crear la carpeta base: " + e.getMessage());
            return;
        }

        Scanner sc = new Scanner(System.in);
        boolean ejecutando = true;

        while (ejecutando) {
            mostrarMenu();
            String opcion = sc.nextLine().trim();

            try {
                switch (opcion) {
                    case "1" -&gt; crearDirectorio(sc);
                    case "2" -&gt; crearFichero(sc);
                    case "3" -&gt; listarContenido();
                    case "4" -&gt; eliminar(sc);
                    case "5" -&gt; ejecutando = false;
                    default -&gt; System.out.println("Opción no válida.");
                }
            } catch (IOException e) {
                System.err.println("Error de E/S: " + e.getMessage());
            }
            System.out.println();
        }

        sc.close();
        System.out.println("Programa finalizado.");
    }

    private static void mostrarMenu() {
        System.out.println("=== Gestión de Ficheros (java.nio) ===");
        System.out.println("1. Crear directorio");
        System.out.println("2. Crear fichero");
        System.out.println("3. Listar contenido");
        System.out.println("4. Eliminar fichero o directorio");
        System.out.println("5. Salir");
        System.out.print("Elige opción: ");
    }

    private static void crearDirectorio(Scanner sc) throws IOException {
        System.out.print("Nombre del directorio: ");
        String nombre = sc.nextLine().trim();
        if (nombre.isEmpty()) {
            System.out.println("El nombre no puede estar vacío.");
            return;
        }

        Path dir = BASE.resolve(nombre);
        if (Files.exists(dir)) {
            System.out.println("Ya existe: " + dir.getFileName());
            return;
        }

        Files.createDirectories(dir);
        System.out.println("Directorio creado: " + dir.toAbsolutePath());
    }

    private static void crearFichero(Scanner sc) throws IOException {
        System.out.print("Nombre del fichero: ");
        String nombre = sc.nextLine().trim();
        if (nombre.isEmpty()) {
            System.out.println("El nombre no puede estar vacío.");
            return;
        }

        Path fichero = BASE.resolve(nombre);
        if (Files.exists(fichero)) {
            System.out.println("Ya existe: " + fichero.getFileName());
            return;
        }

        Files.createFile(fichero);
        System.out.println("Fichero creado: " + fichero.toAbsolutePath());
    }

    private static void listarContenido() throws IOException {
        if (Files.notExists(BASE)) {
            System.out.println("La carpeta base no existe.");
            return;
        }

        try (Stream&lt;Path&gt; contenido = Files.list(BASE)) {
            long count = contenido
                .sorted()
                .peek(entry -&gt; {
                    String tipo = Files.isDirectory(entry) ? "[DIR]" : "[FIC]";
                    System.out.printf("  %s %s%n", tipo, entry.getFileName());
                })
                .count();

            if (count == 0) {
                System.out.println("  (vacío)");
            }
        }
    }

    private static void eliminar(Scanner sc) throws IOException {
        System.out.print("Nombre del fichero o directorio a eliminar: ");
        String nombre = sc.nextLine().trim();
        if (nombre.isEmpty()) {
            System.out.println("El nombre no puede estar vacío.");
            return;
        }

        Path target = BASE.resolve(nombre);
        boolean eliminado = Files.deleteIfExists(target);
        if (eliminado) {
            System.out.println("Eliminado: " + nombre);
        } else {
            System.out.println("No existe: " + nombre);
        }
    }
}
